properties.query:
// The parameter-less ASIM Audit Event parser for Keyring: every row of
// vimAuditEventKeyring, unfiltered. Deployed as ASimAuditEventKeyring.
vimAuditEventKeyring()

// The parameter-less ASIM Audit Event parser for Keyring: every row of
// vimAuditEventKeyring, unfiltered. Deployed as ASimAuditEventKeyring.
vimAuditEventKeyring()

let window = 60m;
let delay = 10m;
let revealThreshold = 20;
// Many secret reveals or private key downloads by one person in a short time.
// Rows can arrive late, so the rule looks back window + delay, and only
// alerts when a row counted arrived in the last window.
// Set by main.bicep: window, delay, revealThreshold
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where Action in ("secret.reveal", "certificate.download_private_key") and Outcome == "success"
| summarize Reveals = count(), Vaults = make_set(Vault, 10), Items = make_set(ItemName, 20),
    ClientIp = take_any(ClientIp), ActorUpn = take_any(ActorUpn),
    FirstTime = min(TimeGenerated), LastTime = max(TimeGenerated), TimeGenerated = max(TimeGenerated),
    LastArrived = max(coalesce(ingestion_time(), TimeGenerated))
    by ActorObjectId
| where Reveals >= revealThreshold and LastArrived > ago(window)

let window = 1h;
let delay = 10m;
// A reveal or private key download from an address not seen for that
// person in the 14 days before. Only for people seen before, so a first
// sign-in doesn't alert. The rule looks back 14 days.
// Reads are taken by when they arrived, so a late row is still looked at
// once.
// Set by main.bicep: window, delay
let Known = KeyringAudit_CL
| where TimeGenerated between (ago(14d) .. ago(window + delay))
| where isnotempty(ActorObjectId) and isnotempty(ClientIp)
| summarize by ActorObjectId, ClientIp;
let People = Known | summarize by ActorObjectId;
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where coalesce(ingestion_time(), TimeGenerated) > ago(window)
| where Action in ("secret.reveal", "certificate.download_private_key") and Outcome == "success"
| where isnotempty(ActorObjectId) and isnotempty(ClientIp)
| join kind=leftsemi People on ActorObjectId
| join kind=leftanti Known on ActorObjectId, ClientIp
| summarize Reads = count(), Vaults = make_set(Vault, 10), Items = make_set(ItemName, 20),
    take_any(ActorUpn, UserAgent), LastTime = max(TimeGenerated), TimeGenerated = max(TimeGenerated)
    by ActorObjectId, ClientIp

let window = 60m;
let delay = 10m;
let probingVaults = 3;
let probingDenied = 5;
// One person denied by Key Vault in several vaults: probing for access.
// Looks back window + delay for late rows; alerts only when a row counted
// arrived in the last window.
// Set by main.bicep: window, delay, probingVaults, probingDenied
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where Outcome == "denied" and isnotempty(Vault)
| summarize Denied = count(), VaultCount = dcount(Vault), Vaults = make_set(Vault, 20),
    Actions = make_set(Action, 10), ClientIp = take_any(ClientIp), ActorUpn = take_any(ActorUpn),
    TimeGenerated = max(TimeGenerated), LastArrived = max(coalesce(ingestion_time(), TimeGenerated))
    by ActorObjectId
| where VaultCount >= probingVaults and Denied >= probingDenied and LastArrived > ago(window)

let window = 15m;
let delay = 10m;
let watchedActions = dynamic(["secret.purge","certificate.purge","key.purge","certificate.download_private_key"]);
let watchedTerms = dynamic(["bulk"]);
let utcOffset = 600 * 1m;
let workStart = 8;
let workEnd = 18;
let workDays = dynamic([1,2,3,4,5]);
// A purge, private key download or other watched action outside working
// hours, in the organisation's own time zone. An action counts if it is in
// watchedActions, or one of the parts of its name (split at "." and "_")
// is in watchedTerms, so "bulk" catches secret.bulk_update or bulk.tag.set
// whatever the bulk change actions end up named.
// Each event is looked at once, in the run after it arrives, so late rows
// are neither missed nor raised twice. Working hours may run past midnight
// (workStart 22, workEnd 6); the day is the local day of the event.
// Set by main.bicep: window, delay, watchedActions, watchedTerms, utcOffset, workStart, workEnd, workDays
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where coalesce(ingestion_time(), TimeGenerated) > ago(window)
| extend Parts = split(replace_string(Action, "_", "."), ".")
| where Action in (watchedActions) or array_length(set_intersect(Parts, watchedTerms)) > 0
| extend LocalTime = TimeGenerated + utcOffset
| extend LocalHour = hourofday(LocalTime), LocalDay = toint(dayofweek(LocalTime) / 1d)
| extend InHours = iff(workStart <= workEnd,
    LocalHour >= workStart and LocalHour < workEnd,
    LocalHour >= workStart or LocalHour < workEnd)
| where not(InHours) or LocalDay !in (workDays)
| project TimeGenerated, LocalTime, Action, Outcome, ReasonCode, ActorObjectId, ActorUpn,
    ClientIp, Vault, ItemKind, ItemName, KvRequestId

let window = 15m;
let delay = 10m;
let attackThreshold = 5;
// Requests Keyring refused as a forged form or a cross-site post: a possible
// attack on Keyring itself.
// Looks back window + delay for late rows; alerts only when a row counted
// arrived in the last window.
// Set by main.bicep: window, delay, attackThreshold
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where Outcome == "refused" and ReasonCode in ("csrf", "cross_site")
| summarize Refused = count(), Reasons = make_set(ReasonCode, 5), Actions = make_set(Action, 10),
    UserAgents = make_set(UserAgent, 5), take_any(ActorObjectId, ActorUpn),
    LastTime = max(TimeGenerated), TimeGenerated = max(TimeGenerated), LastArrived = max(coalesce(ingestion_time(), TimeGenerated))
    by ClientIp
| where Refused >= attackThreshold and LastArrived > ago(window)

let window = 60m;
let delay = 10m;
let shareThreshold = 5;
// Secrets shared through Keyring (#286) that need a look: a share to a
// guest account, or more than shareThreshold shares by one person in the
// window. Rows can arrive late, so the rule looks back window + delay, and
// only alerts when a row counted arrived in the last window.
// Set by main.bicep: window, delay, shareThreshold
KeyringAudit_CL
| where TimeGenerated > ago(window + delay)
| where Action == "share.grant" and Outcome == "success"
| extend PrincipalType = tostring(column_ifexists("SharePrincipalType", "")),
    PrincipalId = tostring(column_ifexists("SharePrincipalId", ""))
| summarize Shares = count(), Guests = countif(PrincipalType == "guest"),
    Recipients = make_set(PrincipalId, 20), Vaults = make_set(Vault, 10), Items = make_set(ItemName, 20),
    ClientIp = take_any(ClientIp), ActorUpn = take_any(ActorUpn),
    FirstTime = min(TimeGenerated), LastTime = max(TimeGenerated), TimeGenerated = max(TimeGenerated),
    LastArrived = max(coalesce(ingestion_time(), TimeGenerated))
    by ActorObjectId
| where (Guests > 0 or Shares > shareThreshold) and LastArrived > ago(window)

let window = 6h;
// Populate with Keyring's outbound IP addresses before enabling this rule.
let keyringIps = dynamic([]);
// Uses AzureDiagnostics by default; replace with infra/sentinel/rules/keyvault-azkv.kql if vaults write to AZKVAuditLogs.
let KeyVaultCalls = AzureDiagnostics
| where ResourceProvider == 'MICROSOFT.KEYVAULT' and Category == 'AuditEvent'
| project TimeGenerated, ResourceId = _ResourceId, OperationName,
    Item = tostring(split(tostring(parse_url(tostring(column_ifexists('requestUri_s', ''))).Path), '/')[2]),
    CallerIpAddress = tostring(column_ifexists('CallerIPAddress', '')),
    CorrelationId = tostring(column_ifexists('CorrelationId', '')),
    CallerObjectId = coalesce(
        tostring(column_ifexists('identity_claim_http_schemas_microsoft_com_identity_claims_objectidentifier_g', '')),
        tostring(column_ifexists('identity_claim_oid_g', '')));
// No Keyring events at all in the window while Key Vault logged calls from
// Keyring's outbound addresses that only an audited action makes: the audit
// sink is broken or turned off.
// Set by main.bicep: window, KeyVaultCalls, keyringIps
let KeyringEvents = toscalar(KeyringAudit_CL | where TimeGenerated > ago(window) | count);
KeyVaultCalls
| where TimeGenerated > ago(window)
| where CallerIpAddress in (keyringIps)
| where OperationName in ("SecretGet", "SecretSet", "SecretDelete", "SecretPurge", "SecretRecover",
    "CertificateImport", "CertificateCreate", "CertificateDelete", "CertificatePurge", "CertificateRecover",
    "KeyCreate", "KeyRotate", "KeyDelete", "KeyPurge", "KeyRecover")
| summarize KeyVaultCallCount = count(), Operations = make_set(OperationName, 20),
    CallerIpAddress = take_any(CallerIpAddress), LastTime = max(TimeGenerated), TimeGenerated = max(TimeGenerated)
    by ResourceId
| where KeyringEvents == 0

// Populate with Keyring's outbound IP addresses before enabling this rule.
let keyringIps = dynamic([]);
// Uses AzureDiagnostics by default; replace with infra/sentinel/rules/keyvault-azkv.kql if vaults write to AZKVAuditLogs.
let KeyVaultCalls = AzureDiagnostics
| where ResourceProvider == 'MICROSOFT.KEYVAULT' and Category == 'AuditEvent'
| project TimeGenerated, ResourceId = _ResourceId, OperationName,
    Item = tostring(split(tostring(parse_url(tostring(column_ifexists('requestUri_s', ''))).Path), '/')[2]),
    CallerIpAddress = tostring(column_ifexists('CallerIPAddress', '')),
    CorrelationId = tostring(column_ifexists('CorrelationId', '')),
    CallerObjectId = coalesce(
        tostring(column_ifexists('identity_claim_http_schemas_microsoft_com_identity_claims_objectidentifier_g', '')),
        tostring(column_ifexists('identity_claim_oid_g', '')));
// A Key Vault SecretGet from Keyring's outbound addresses with no Keyring
// event to match it, joined on Key Vault's CorrelationId and Keyring's
// KvRequestId. A rollback reads the value and then writes it, so its event
// carries the later call's ID: a SecretGet with no ID match still counts as
// matched if the same person has a reveal, rollback, copy or private key download
// event on the same vault and item within two minutes.
// Looks at Key Vault calls from one to two hours ago, so Keyring's events
// have had time to arrive.
// NOT YET CHECKED on a real vault: that Key Vault records Keyring's
// x-ms-client-request-id as CorrelationId. Off by default until the
// real-vault checklist row passes.
// Set by main.bicep: KeyVaultCalls, keyringIps
let Gets = KeyVaultCalls
| where TimeGenerated between (ago(2h) .. ago(1h))
| where CallerIpAddress in (keyringIps) and OperationName == "SecretGet"
| extend VaultName = tolower(tostring(split(ResourceId, "/")[-1]));
let Events = KeyringAudit_CL
| where TimeGenerated > ago(3h)
| where isnotempty(KvRequestId)
| project KvRequestId;
let ByPerson = KeyringAudit_CL
| where TimeGenerated > ago(3h)
| where Action in ("secret.reveal", "secret.rollback", "secret.copy.read", "certificate.download_private_key")
| project EventTime = TimeGenerated, ActorObjectId, EventVault = tolower(Vault), ItemName;
Gets
| join kind=leftanti Events on $left.CorrelationId == $right.KvRequestId
| join kind=leftouter ByPerson on $left.CallerObjectId == $right.ActorObjectId, $left.VaultName == $right.EventVault, $left.Item == $right.ItemName
| summarize Near = countif(isnotempty(EventTime) and abs(datetime_diff('second', EventTime, TimeGenerated)) <= 120)
    by TimeGenerated, ResourceId, VaultName, Item, CallerObjectId, CallerIpAddress, CorrelationId
| where Near == 0
| project-away Near

// Secret values read through Keyring: who, which vault and item, from where.
// The same question as "Secret values read" on Keyring's audit page, which
// reads Key Vault's log. Set who to part of a sign-in name to narrow it.
let who = "";
KeyringAudit_CL
| where Action == "secret.reveal"
| where isempty(who) or ActorUpn contains who or ActorObjectId =~ who
| project TimeGenerated, ActorUpn, ActorObjectId, Vault, ItemName, ItemVersion, Outcome, ReasonCode, ClientIp, KvRequestId, Reason, Ticket
| order by TimeGenerated desc

// Everything one person did through Keyring. Set who to their exact
// sign-in name or object ID first.
let who = "name@example.com";
KeyringAudit_CL
| where ActorUpn =~ who or ActorObjectId =~ who
| project TimeGenerated, Action, Outcome, ReasonCode, Vault, ItemKind, ItemName, ClientIp, UserAgent, SessionRef, Reason, Ticket
| order by TimeGenerated desc

// Key Vault's log and Keyring's log side by side for one vault: every Key
// Vault call next to the Keyring event whose KvRequestId matches its
// CorrelationId. A call with no Keyring event isn't proof it came from
// elsewhere: a rollback reads the old value and then writes it, and its
// event carries only the write's request ID. Check the caller and address. Change AZKVAuditLogs to AzureDiagnostics, and the
// columns as in docs/sentinel.md, if the vault logs there. The CorrelationId
// match is still to be confirmed on a real vault.
let vaultName = "kv-app-prod";
let Keyring = KeyringAudit_CL
| where Vault =~ vaultName and isnotempty(KvRequestId)
| project KvRequestId, Action, Outcome, ActorUpn, ClientIp, Reason, Ticket;
AZKVAuditLogs
| where _ResourceId endswith strcat("/vaults/", tolower(vaultName))
| extend CorrelationId = tostring(column_ifexists("CorrelationId", ""))
| join kind=leftouter Keyring on $left.CorrelationId == $right.KvRequestId
| project TimeGenerated, OperationName, ResultSignature, CallerIpAddress, Action, Outcome, ActorUpn, ClientIp, Reason, Ticket
| order by TimeGenerated desc
